int def scoreAge(int:age) {
    if (age <= 30) {
        return 25;
    } else if (age <= 40) {
        return 22;
    } else if (age <= 50) {
        return 17;
    } else if (age <= 60) {
        return 10;
    } else {
        return 4;
    }
}


int def scoreOccupation(int:occupationClass) {
    if (occupationClass == 1) {
        return 25;
    } else if (occupationClass == 2) {
        return 22;
    } else if (occupationClass == 3) {
        return 17;
    } else if (occupationClass == 4) {
        return 11;
    } else {
        return 5;
    }
}


int def scoreBmi(double:bmi) {
    if (bmi >= 18.5 && bmi <= 24.0) {
        return 20;
    } else if (bmi > 24.0 && bmi <= 28.0) {
        return 14;
    } else if (bmi > 28.0 && bmi <= 32.0) {
        return 7;
    } else {
        return 3;
    }
}


int def scoreSmoker(boolean:smoker) {
    if (smoker) {
        return 4;
    } else {
        return 10;
    }
}


int def scoreChronic(str:chronicDisease) {
    if (chronicDisease == "NONE") {
        return 20;
    } else if (chronicDisease == "HYPERTENSION") {
        return 10;
    } else if (chronicDisease == "DIABETES") {
        return 6;
    } else {
        return 0;
    }
}


str def underwritingResult(int:totalScore, str:chronicDisease, str:productType) {
    str result = "POSTPONE";
    if (totalScore >= 55) {
        result = "LOADED";
    }
    if (totalScore >= 70) {
        result = "STANDARD";
    }
    if (totalScore >= 85) {
        result = "PREFERRED";
    }
    if (chronicDisease == "DIABETES") {
        if (productType == "MEDICAL") {
            result = "EXCLUSION";
        }
        if (productType == "CRITICAL_ILLNESS") {
            result = "EXCLUSION";
        }
    }
    if (chronicDisease == "HYPERTENSION") {
        if (productType == "MEDICAL") {
            result = "EXCLUSION";
        }
    }
    return result;
}


int def extraPremiumRate(str:result) {
    if (result == "LOADED") {
        return 25;
    } else {
        return 0;
    }
}


int def premiumDiscountRate(str:result) {
    if (result == "PREFERRED") {
        return 10;
    } else {
        return 0;
    }
}


int def maxSumInsuredWan(int:occupationClass, int:age) {
    if (occupationClass <= 2 && age <= 40) {
        return 200;
    } else if (occupationClass <= 3 && age <= 50) {
        return 100;
    } else if (occupationClass <= 4) {
        return 60;
    } else {
        return 30;
    }
}
